/// Decodes a Base64 [encoded] string into a [Uint8List], wrapping any
/// [FormatException] in a [CodableException].
Uint8List decodeJsonBase64Bytes(String encoded) {
  try {
    return base64Decode(encoded);
  } on FormatException catch (e) {
    throw CodableException('Invalid base64 string for bytes: ${e.message}');
  }
}

/// Maps an in-memory Dart object to a format-agnostic [ValueKind].
ValueKind dartObjectToValueKind(Object? v) => switch (v) {
  null => ValueKind.nullValue,
  bool() => ValueKind.boolean,
  num() => ValueKind.number,
  String() => ValueKind.string,
  Uint8List() => ValueKind.bytes,
  List() => ValueKind.list,
  Map() => ValueKind.map,
  _ => throw CodableException('Unexpected value kind for $v'),
};

/// Parses a JSON object from [reader] into an in-memory `Map<String, Object?>`.
Map<String, Object?> parseObjectFromReader(JsonTokenReader reader) {
  reader.beginObject();
  final map = <String, Object?>{};
  while (reader.moveNext()) {
    final key = reader.nextName();
    map[key] = _parseValueFromReader(reader);
  }
  reader.endObject();
  return map;
}

Object? _parseValueFromReader(JsonTokenReader reader) {
  final type = reader.peek();
  switch (type) {
    case JsonTokenType.nullValue:
      reader.readNull();
      return null;
    case JsonTokenType.boolean:
      return reader.readBool();
    case JsonTokenType.number:
      return reader.readNum();
    case JsonTokenType.string:
      return reader.readString();
    case JsonTokenType.beginObject:
      return parseObjectFromReader(reader);
    case JsonTokenType.beginArray:
      reader.beginArray();
      final list = <Object?>[];
      while (reader.moveNext()) {
        list.add(_parseValueFromReader(reader));
      }
      reader.endArray();
      return list;
    default:
      reader.skipValue();
      return null;
  }
}

Uint8List _decodeObjectBytes(Object? v) {
  if (v is Uint8List) return v;
  if (v is String) return decodeJsonBase64Bytes(v);
  if (v is List<Object?>) return _decodeByteListFromObjects(v);
  throw CodableException('Expected base64 string or byte list, found $v');
}

Uint8List _decodeByteListFromObjects(List<Object?> v) {
  final out = Uint8List(v.length);
  for (var i = 0; i < v.length; i++) {
    final e = v[i];
    if (e is! int || e < 0 || e > 255) {
      throw CodableException('Expected byte 0..255 in list, found $e');
    }
    out[i] = e;
  }
  return out;
}

