mixin _DartObjectSequentialMixin {
  Map<Object, Object?> get _userInfo;
  bool _hasCurrentValue();
  Object? _peekCurrentValue();
  void _commitCurrentValue();

  Object? _takeCurrentValue() {
    final v = _peekCurrentValue();
    _commitCurrentValue();
    return v;
  }

  ValueKind peekKind() => dartObjectToValueKind(_peekCurrentValue());

  bool isNextNull() => _hasCurrentValue() && _peekCurrentValue() == null;

  void readNull() {
    final v = _peekCurrentValue();
    if (v != null) {
      throw CodableException('Expected null, found $v');
    }
    _commitCurrentValue();
  }

  int readInt() {
    final v = _peekCurrentValue();
    if (v is int) {
      _commitCurrentValue();
      return v;
    }
    throw CodableException('Expected int, found $v');
  }

  double readDouble() {
    final v = _peekCurrentValue();
    if (v is num) {
      _commitCurrentValue();
      return v.toDouble();
    }
    throw CodableException('Expected double, found $v');
  }

  num readNum() {
    final v = _peekCurrentValue();
    if (v is num) {
      _commitCurrentValue();
      return v;
    }
    throw CodableException('Expected num, found $v');
  }

  String readString() {
    final v = _peekCurrentValue();
    if (v is String) {
      _commitCurrentValue();
      return v;
    }
    throw CodableException('Expected String, found $v');
  }

  bool readBool() {
    final v = _peekCurrentValue();
    if (v is bool) {
      _commitCurrentValue();
      return v;
    }
    throw CodableException('Expected bool, found $v');
  }

  Uint8List readBytes() {
    final bytes = _decodeObjectBytes(_peekCurrentValue());
    _commitCurrentValue();
    return bytes;
  }

  Decoder nestedDecoder() =>
      DartObjectDecoder(_takeCurrentValue(), userInfo: _userInfo);
}

/// Sequential [KeyedDecoder] over a parsed `Map<String, Object?>`.
final class DartObjectKeyedDecoder
    with BaseKeyedDecoderMixin, _DartObjectSequentialMixin
    implements KeyedDecoder {
  final Map<String, Object?> _map;
  @override
  final Map<Object, Object?> _userInfo;
  late final List<String> _keys = _map.keys.toList(growable: false);
  int _index = 0;
  String? _activeKey;
  Object? _activeValue;
  bool _hasActive = false;

  DartObjectKeyedDecoder(this._map, this._userInfo);

  @override
  bool moveNextKey() {
    if (_hasActive) return true;
    if (_index >= _keys.length) return false;
    final key = _keys[_index++];
    _activeKey = key;
    _activeValue = _map[key];
    _hasActive = true;
    return true;
  }

  @override
  bool _hasCurrentValue() => moveNextKey();

  @override
  Object? _peekCurrentValue() {
    if (!moveNextKey()) {
      throw const CodableException('No more keys in object');
    }
    return _activeValue;
  }

  @override
  void _commitCurrentValue() {
    _hasActive = false;
    _activeKey = null;
    _activeValue = null;
  }

  @override
  String nextKey() {
    if (!moveNextKey()) {
      throw const CodableException('No more keys in object');
    }
    return _activeKey!;
  }

  @override
  String? peekKey() => moveNextKey() ? _activeKey : null;

  @override
  int selectKeyIndex(KeyOptions options) =>
      moveNextKey() ? options.indexOf(_activeKey!) : -1;

  @override
  void skipValue() {
    if (moveNextKey()) _commitCurrentValue();
  }
}

/// Sequential [MapDecoder] over a parsed `Map<String, Object?>`.
final class DartObjectMapDecoder implements MapDecoder {
  final Map<String, Object?> _map;
  final Map<Object, Object?> _userInfo;
  late final List<String> _keys = _map.keys.toList(growable: false);
  late final JsonMapKeyDecoder _keyDecoder = JsonMapKeyDecoder(_userInfo);
  int _index = 0;
  Object? _currentValue;
  bool _hasCurrent = false;

  DartObjectMapDecoder(this._map, this._userInfo);

  @override
  int? get length => _map.length;

  @override
  bool moveNextEntry() {
    if (_index >= _keys.length) {
      _hasCurrent = false;
      return false;
    }
    final key = _keys[_index++];
    _keyDecoder.key = key;
    _currentValue = _map[key];
    _hasCurrent = true;
    return true;
  }

  @override
  Decoder keyDecoder() {
    if (!_hasCurrent) {
      throw const CodableException('No active map entry');
    }
    return _keyDecoder;
  }

  @override
  Decoder valueDecoder() {
    if (!_hasCurrent) {
      throw const CodableException('No active map entry');
    }
    return DartObjectDecoder(_currentValue, userInfo: _userInfo);
  }
}

/// Sequential [UnkeyedDecoder] over a parsed `List<Object?>`.
final class DartObjectUnkeyedDecoder
    with BaseUnkeyedDecoderMixin, _DartObjectSequentialMixin
    implements UnkeyedDecoder {
  final List<Object?> _list;
  @override
  final Map<Object, Object?> _userInfo;
  int _index = 0;

  DartObjectUnkeyedDecoder(this._list, this._userInfo);

  @override
  int? get length => _list.length;

  @override
  bool moveNext() => _index < _list.length;

  @override
  bool _hasCurrentValue() => _index < _list.length;

  @override
  Object? _peekCurrentValue() {
    if (_index >= _list.length) {
      throw const CodableException('No more elements in array');
    }
    return _list[_index];
  }

  @override
  void _commitCurrentValue() {
    _index++;
  }

  @override
  void skipElement() {
    _takeCurrentValue();
  }
}

